// src/components/GachaComponents.js
// Export gacha screens and components

export { default as GachaScreen } from '../screens/GachaScreen';
export { default as CharacterCollectionScreen } from '../screens/CharacterCollectionScreen';

// WorkoutVerificationWidget component
import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Modal,
  Alert,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useApp } from '../context/AppContext';

const RARITY_COLORS = {
  common: '#95A5A6',
  uncommon: '#27AE60',
  rare: '#3498DB',
  epic: '#9B59B6',
  legendary: '#F39C12'
};

export const WorkoutVerificationWidget = ({ workout, onVerificationComplete }) => {
  const { userStats, updateUserStats } = useApp();
  const [showVerification, setShowVerification] = useState(false);

  const handleVerification = () => {
    setShowVerification(true);
  };

  const handleVerificationComplete = () => {
    setShowVerification(false);
    onVerificationComplete?.();
  };

  if (!workout) return null;

  return (
    <>
      <TouchableOpacity style={styles.verificationButton} onPress={handleVerification}>
        <Ionicons name="checkmark-circle" size={24} color="#27AE60" />
        <Text style={styles.verificationText}>Verify Workout</Text>
      </TouchableOpacity>

      <Modal
        visible={showVerification}
        transparent={true}
        animationType="slide"
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <Text style={styles.modalTitle}>Workout Verification</Text>
            <Text style={styles.modalSubtitle}>
              Great job completing your workout! You've earned rewards.
            </Text>
            
            <View style={styles.rewardsContainer}>
              <View style={styles.rewardItem}>
                <Ionicons name="star" size={24} color="#F39C12" />
                <Text style={styles.rewardText}>+50 XP</Text>
              </View>
              <View style={styles.rewardItem}>
                <Ionicons name="diamond" size={24} color="#9B59B6" />
                <Text style={styles.rewardText}>+1 Gacha Pull</Text>
              </View>
            </View>

            <TouchableOpacity 
              style={styles.verifyButton}
              onPress={handleVerificationComplete}
            >
              <Text style={styles.verifyButtonText}>Claim Rewards</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </>
  );
};

const styles = StyleSheet.create({
  verificationButton: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#f8f9fa',
    padding: 12,
    borderRadius: 8,
    marginVertical: 8,
    gap: 8,
  },
  verificationText: {
    fontSize: 16,
    fontWeight: '600',
    color: '#27AE60',
  },
  modalOverlay: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    justifyContent: 'center',
    alignItems: 'center',
  },
  modalContent: {
    backgroundColor: '#fff',
    borderRadius: 16,
    padding: 24,
    margin: 20,
    alignItems: 'center',
    minWidth: 300,
  },
  modalTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 8,
  },
  modalSubtitle: {
    fontSize: 14,
    color: '#666',
    textAlign: 'center',
    marginBottom: 20,
    lineHeight: 20,
  },
  rewardsContainer: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    width: '100%',
    marginBottom: 24,
  },
  rewardItem: {
    alignItems: 'center',
    gap: 8,
  },
  rewardText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#333',
  },
  verifyButton: {
    backgroundColor: '#27AE60',
    paddingHorizontal: 24,
    paddingVertical: 12,
    borderRadius: 20,
  },
  verifyButtonText: {
    color: '#fff',
    fontSize: 16,
    fontWeight: '600',
  },
});
